export type Format = 'json' | 'yaml' | 'text' | 'csv'

/**
 * The version of the JSON format this build reads and writes
 * (`spec/json-format.md`).
 */
export declare const FORMAT_VERSION: number

/**
 * A grid with its settings and limits.
 *
 * # Errors
 *
 * `RuleDefinitionError` for an unknown hit policy or aggregate, or a
 * `strict` that is not a boolean; `RegistryError` for an unknown logic; a
 * `TypeError` or `RangeError` for bad limits.
 */
export declare function gridNew(hitPolicy: unknown, aggregate: unknown, logic: unknown, strict: unknown, limits: unknown): NativeGrid

/** The name of a hit policy (`spec/rules.md`). */
export type HitPolicy = 'first' | 'priority' | 'unique' | 'any' | 'rule_order' | 'collect'

/**
 * Limits for reading documents and inputs; each one left out keeps the core's
 * default. `maxSize` sets the largest text of every format (JSON, YAML, the
 * rule syntax and CSV); `maxYamlSize` and `maxTextSize` then lower or raise
 * YAML's and the rule syntax's.
 */
export interface Limits {
  /** The largest document, in bytes of UTF-8. */
  maxSize?: number
  /** The deepest nesting of arrays and objects. */
  maxNesting?: number
  /** The deepest condition or payload value, in nodes. */
  maxDepth?: number
  /** The most cells and nodes a decision table may build. */
  maxTableSize?: number
  /** The largest YAML text, in bytes. */
  maxYamlSize?: number
  /** The largest text in the rule syntax or CSV, in bytes. */
  maxTextSize?: number
  /**
   * The most values read from the native data of one input (1,000,000 by
   * default; `spec/data-model.md`, *Reading native data*, *Limits*).
   */
  maxValues?: number
  /**
   * The most segments a field path may have, in every format (256 by
   * default); `F` and `field` check the default.
   */
  maxPathSegments?: number
}

/**
 * The JSON form of the core's `limit_exceeded` for a constant or metadata
 * beyond `max_values`, with the `rule` when it is known
 * (`spec/data-model.md`, *Reading native data*, *Limits*).
 */
export declare function maxValuesErrorData(maxValues: number, rule?: string | undefined | null): string

/**
 * Arithmetic.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeArith(op: string, left: Node, right: Node): Node

/**
 * A range test.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeBetween(operand: Node, low: Node, high: Node, closed: string): Node

/** A node's children, in order. */
export declare function nodeChildren(parent: Node): Array<Node>

/**
 * `left op right`.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeCompare(op: string, left: Node, right: Node): Node

/**
 * `and` or `or` of the nodes of `operands`.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeConnective(tag: string, operands: NodeList): Node

/**
 * A constant, in the reader's encoding.
 *
 * # Errors
 *
 * `ExpressionError` for a value that is not a constant.
 */
export declare function nodeConstant(wire: string): Node

/** A node's tag, kind and own data, as JSON. */
export declare function nodeDetails(node: Node): string

/**
 * A field, by its path of keys and indices.
 *
 * # Errors
 *
 * `ExpressionError` for an invalid path.
 */
export declare function nodeField(path: Array<string | number>): Node

/**
 * Membership in constants, a list in the reader's encoding.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeIsIn(operand: Node, wire: string): Node

/**
 * A regular expression search.
 *
 * # Errors
 *
 * `ExpressionError` for a pattern that does not compile.
 */
export declare function nodeMatches(operand: Node, pattern: string): Node

/**
 * An int or a decimal rounded to `scale` digits after the point.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeRound(operand: Node, scale: number, mode: string): Node

/** Whether two nodes are structurally identical (`spec/ast.md`). */
export declare function nodeSameAs(left: Node, right: Node): boolean

/**
 * `starts_with`, `ends_with` or `contains`.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeStringTest(op: string, operand: Node, text: string): Node

/**
 * Evaluate `node` (a `Node`) on native data, as a condition or as a value:
 * its result tree.
 *
 * # Errors
 *
 * As `Node.evaluateTree` and `Node.evaluateValueTree`.
 */
export declare function nodeTree(node: Node, data: unknown, options: unknown, value: boolean): NativeTree

/**
 * `not`, `is_null`, `abs` or `neg`.
 *
 * # Errors
 *
 * `ExpressionError`, as the core reports it.
 */
export declare function nodeUnary(tag: string, operand: Node): Node

/** How a text is read: its format (JSON when left out) and limits. */
export interface ReadOptions {
  /** The format: `"json"` (the default), `"yaml"`, `"text"` or `"csv"`. */
  format?: Format
  /** The limits; each one left out keeps the core's default. */
  limits?: Limits
}

/** A rule's tags, metadata, action name, id and effective id, as JSON. */
export declare function ruleDetails(rule: NativeRule): string

/**
 * A rule.
 *
 * # Errors
 *
 * `RuleDefinitionError` or `ExpressionError`, as the core reports them.
 */
export declare function ruleNew(name: string, when: Node, then: NodeList, priority: string, tags: string[], description?: string | null, metadata?: string | null, action?: string | null, id?: string | null): NativeRule

/** A rule's condition and payload values. */
export declare function ruleNodes(rule: NativeRule): Array<Node>

/** A rule's name, priority, description and payload keys, as JSON. */
export declare function ruleParts(rule: NativeRule): string

/**
 * A rule set of `rules`, with its options as given.
 *
 * # Errors
 *
 * `RuleDefinitionError` or `RegistryError`, as the core reports them.
 */
export declare function ruleSetNew(rules: RuleList, hitPolicy: unknown, aggregate: unknown, logic: unknown, strict: unknown): RuleSet

/** A rule set's rules, in order. */
export declare function ruleSetRules(ruleset: RuleSet): Array<NativeRule>

/**
 * One rule written in the text syntax, under `limits`.
 *
 * # Errors
 *
 * `RuleSyntaxError`, `ExpressionError` or `RuleDefinitionError`, as the core
 * reports them; `FormatError` beyond the limits.
 */
export declare function ruleText(text: string | Uint8Array, limits?: Limits | null): NativeRule

/**
 * The result tree of the condition of the rule at `position` in `decision`.
 *
 * # Errors
 *
 * A `RangeError` for a position out of the rule set.
 */
export declare function ruleTree(decision: Decision, position: number): NativeTree

/**
 * Register the JavaScript half of the binding; `index.js` calls it once when
 * the package loads.
 *
 * # Errors
 *
 * If the environment cannot hold the hooks.
 */
export declare function setHooks(hooks: object): void

/**
 * The text of a document the core wrote, with each float that holds an
 * integer as `{"$float": n}`, for `toJSON()`: `JSON.stringify` of what
 * `JSON.parse` makes of it means the same document (`common::out::stringifiable`).
 */
export declare function stringifiable(text: string): string

/**
 * The summary with the rules whose action is code marked, in `format`.
 *
 * # Errors
 *
 * `UnsupportedError` for CSV.
 */
export declare function summaryWith(ruleset: RuleSet, actions: Array<boolean>, format: unknown): string

/**
 * How one condition node is evaluated (`spec/ast.md`, *Evaluating one
 * node*).
 */
export interface TreeOptions {
  /** The logic: only `"boolean"`, the default, for now. */
  logic?: string
  /** Whether evaluation is strict; `false` by default. */
  strict?: boolean
  /**
   * The limits: `maxValues` for native data, the others for an input given
   * as JSON.
   */
  limits?: Limits
}

/** A crisp truth value. */
export type Truth = 'true' | 'false' | 'unknown'

/** How one value node is evaluated. */
export interface ValueTreeOptions {
  /** Whether evaluation is strict; `false` by default. */
  strict?: boolean
  /**
   * The limits: `maxValues` for native data, the others for an input given
   * as JSON.
   */
  limits?: Limits
}

/** The version of the package. */
export declare function version(): string

/**
 * The condition document of a node, in `format`.
 *
 * # Errors
 *
 * `UnsupportedError` for CSV.
 */
export declare function writeCondition(node: Node, format: unknown): string

/**
 * The rule document of a rule, in `format`.
 *
 * # Errors
 *
 * `UnsupportedError` for CSV, and in text for metadata.
 */
export declare function writeRule(rule: NativeRule, format: unknown): string
